-- Подробные тексты статей справки (понятные инструкции + схема интерфейса).

update help_doc_article a
set body_md = E'## Зачем нужна сводка\nГлавная страница показывает вашу личную загрузку: какие задачи назначены, что изменилось за последние дни, и мини-графики активности команды. Это точка входа после логина.\n\n## Как открыть\nВ боковом меню нажмите **TaskPulse** (первый пункт) или перейдите по адресу команды без суффикса - откроется сводка.\n\n## Что на экране\n- **Мои задачи** - список карточек с названием, проектом и статусом.\n- **Мини-графики** - динамика по истории переводов статусов (данные из task_status_history).\n- **Шапка** - кнопка «+» для новой задачи, профиль, настройки, тема.\n\n## Основные действия\n1. Клик по задаче в списке открывает **карточку задачи** (модальное окно).\n2. Создайте задачу через «+» в шапке, не покидая сводку.\n3. После работы на досках вернитесь на сводку, чтобы увидеть обновлённые назначения.\n\n## Советы\nЕсли список пуст - проверьте фильтры на досках и что вам назначены задачи. После долгого простоя обновите страницу (Ctrl+F5).\n\n![Схема: меню, шапка и рабочая область](/static/source/help/illustrations/doc-preview.svg)',
    title = 'Сводка - главная страница'
from help_doc_section s
where a.section_id = s.id and s.kind = 'page' and s.slug = 'index' and a.slug = 'guide';

update help_doc_article a
set body_md = E'## Зачем нужен раздел «Задачи»\nЗдесь собраны **все задачи команды** в одной таблице: удобно искать по проекту, статусу и исполнителю, не открывая каждую доску отдельно.\n\n## Как открыть\nБоковое меню → **Задачи**.\n\n## Что на экране\n- Таблица с колонками: код, название, проект, статус, исполнитель, сроки.\n- Фильтры вверху (если доступны в вашей сборке).\n- Те же кнопки шапки, что и на других страницах.\n\n## Основные действия\n1. **Клик по строке** - открывается модальное окно задачи с полным описанием и историей.\n2. **Кнопка «+»** - создание новой задачи (выберите проект и доску в форме).\n3. Сортируйте визуально по статусу, чтобы найти просроченные и «зависшие» задачи.\n\n## Типичные сценарии\n- Руководитель смотрит загрузку команды перед планёркой.\n- Участник ищет задачу по названию, если потерял её на доске.\n\n![Схема интерфейса TaskPulse](/static/source/help/illustrations/doc-preview.svg)',
    title = 'Задачи - таблица команды'
from help_doc_section s
where a.section_id = s.id and s.kind = 'page' and s.slug = 'tasks' and a.slug = 'guide';

update help_doc_article a
set body_md = E'## Зачем нужны «Проекты»\nПроект - это рабочее пространство команды: доски, задачи и отчёты. Здесь создают новые проекты и переходят к Kanban, List или Scrum.\n\n## Как открыть\nМеню → **Проекты** → подменю «Мои проекты» / список карточек на странице.\n\n## Типы проектов\n- **List** - табличные доски, удобно для регламентов и очередей.\n- **Kanban** - колонки по статусам, классический поток.\n- **Scrum** - спринты, бэклог, отдельная доска спринта.\n\n## Основные действия\n1. **Создать проект** - кнопка на странице, укажите название, ключ (3 буквы) и тип.\n2. **Открыть проект** - клик по карточке ведёт на доску по типу.\n3. **Проекты организации** - все проекты юрлица (подменю).\n4. **Архивные проекты** - снятые с активной работы (см. отдельную статью).\n\n## Что важно помнить\nАрхивный проект не попадает в аналитику портфеля. Ключ проекта используется в URL досок (`/p/КОД/...`).\n\n![Схема интерфейса](/static/source/help/illustrations/doc-preview.svg)',
    title = 'Проекты - список и создание'
from help_doc_section s
where a.section_id = s.id and s.kind = 'page' and s.slug = 'projects' and a.slug = 'guide';

update help_doc_article a
set body_md = E'## Зачем нужен архив проектов\nКогда проект завершён или заморожен, его **архивируют**, чтобы не мешал в ежедневной работе и не искажал метрики. Задачи и история сохраняются.\n\n## Как открыть\nМеню → **Проекты** → **Архивные проекты**.\n\n## Что вы увидите\n- Сетка карточек архивных проектов (без кнопки «Открыть проект» на карточке).\n- На каждой карточке обычно доступно действие **Восстановить**.\n- Статус «архивный» виден по оформлению карточки.\n\n## Основные действия\n1. **Восстановить** - проект снова появится в активном списке, команда сможет открыть доски.\n2. Просмотр метаданных на карточке (название, тип, дата архивации - если отображается).\n\n## Чего нет в архиве\n- Быстрого перехода «Открыть проект» с карточки архива (так задумано, чтобы не путать с активными).\n- Учёта в сводной **аналитике портфеля** - архивные проекты исключены из KPI.\n\n## Когда архивировать\nПроект закрыт, договор выполнен, или команда перешла на новый контур работ. Перед архивацией убедитесь, что важные задачи в статусе «Готово».\n\n![Схема интерфейса](/static/source/help/illustrations/doc-preview.svg)',
    title = 'Архив проектов'
from help_doc_section s
where a.section_id = s.id and s.kind = 'page' and s.slug = 'projects-archive' and a.slug = 'guide';

update help_doc_article a
set body_md = E'## Зачем нужна страница «Команда»\nЗдесь виден состав команды, роли, отделы и должности. Администратор приглашает новых людей и меняет права.\n\n## Как открыть\nБоковое меню → **Команда**.\n\n## Что на экране\n- **Поиск** (как на странице команды) - по имени, должности, отделу.\n- **Фильтры** по отделу и должности (выпадающие списки).\n- **Сетка карточек** участников с аватаром и краткой информацией.\n- Кнопка **Добавить участника** (для администратора).\n\n## Основные действия\n1. Откройте карточку участника - сообщение на email, смена роли/должности (если есть права).\n2. Пригласите коллегу: email + роль (участник, администратор, наблюдатель).\n3. Используйте поиск, чтобы быстро найти человека в большой команде.\n\n## Роли\n- **Администратор** - приглашения, смена ролей.\n- **Участник** - работа с задачами и досками.\n- **Наблюдатель** - просмотр без редактирования (если включено в вашей политике).\n\n![Схема интерфейса](/static/source/help/illustrations/doc-preview.svg)',
    title = 'Команда - участники и роли'
from help_doc_section s
where a.section_id = s.id and s.kind = 'page' and s.slug = 'team' and a.slug = 'guide';

update help_doc_article a
set body_md = E'## Зачем нужна аналитика\nРаздел показывает **метрики команды за период**: KPI, velocity, CFD, отчёты по проектам и сравнение. Период в шапке страницы влияет на расчёты.\n\n## Как открыть\nМеню → **Аналитика** → вкладки Обзор / Отчёты / Диаграммы / Сравнение.\n\n## Вкладки\n- **Обзор** - сводные KPI, velocity, кривая CFD.\n- **Отчёты** - таблица показателей по проектам.\n- **Диаграммы** - распределение по статусам и приоритетам.\n- **Сравнение** - несколько проектов на одном графике.\n\n## Период\nСелектор **7–180 дней** в шапке аналитики. Все графики верхнего блока пересчитываются при смене периода.\n\n## Ограничения\n**Архивные проекты не участвуют** в портфельной аналитике. Задачи без активности в периоде могут не попасть в срез KPI.\n\n## Советы\nПеред отчётом руководству выберите период «30 дней», сравните вкладки Обзор и Отчёты.\n\n![Схема интерфейса](/static/source/help/illustrations/doc-preview.svg)',
    title = 'Аналитика - метрики команды'
from help_doc_section s
where a.section_id = s.id and s.kind = 'page' and s.slug = 'analytics' and a.slug = 'guide';

update help_doc_article a
set body_md = E'## Зачем Kanban-доска\nВизуальный поток задач: колонки = статусы, карточки перетаскиваются. Подходит для непрерывной работы без спринтов.\n\n## Как открыть\n**Проекты** → карточка проекта типа Kanban → или URL `/p/КОД/kanban`.\n\n## Что на экране\n- Колонки: Очередь, В работе, Тестирование, Готово (набор зависит от настроек доски).\n- Карточки с исполнителем, приоритетом, сроком.\n- Фильтры по людям и приоритету.\n\n## Основные действия\n1. **Перетащите карточку** - смена статуса, запись в историю.\n2. **Клик по карточке** - модальное окно задачи.\n3. Перевод в **«Готово»** архивирует задачу (она исчезнет с доски - это нормально).\n\n## Отличие от Scrum\nНет спринтов и бэклога - весь поток на одной доске.\n\n![Схема интерфейса](/static/source/help/illustrations/doc-preview.svg)',
    title = 'Доска Kanban'
from help_doc_section s
where a.section_id = s.id and s.kind = 'page' and s.slug = 'board-kanban' and a.slug = 'guide';

update help_doc_article a
set body_md = E'## Зачем List-доска\nПроекты типа **List** показывают доски в **табличном виде**: удобно для регламентов, чек-листов и последовательных процессов.\n\n## Как открыть\nПроект типа List → **Доски** (`/p/КОД/boards`).\n\n## Что на экране\n- Переключатель досок проекта.\n- Таблица задач по выбранной доске.\n- Блоки отчётов/таймлайна (если включены в интерфейсе).\n\n## Основные действия\n1. Выберите доску в списке.\n2. Откройте задачу кликом по строке.\n3. Создайте задачу через «+» в шапке, указав этот проект.\n\n![Схема интерфейса](/static/source/help/illustrations/doc-preview.svg)',
    title = 'Доска List'
from help_doc_section s
where a.section_id = s.id and s.kind = 'page' and s.slug = 'board-list' and a.slug = 'guide';

update help_doc_article a
set body_md = E'## Зачем Scrum-доска\nИтерационная работа: **бэклог → спринт → доска спринта**. Есть планирование и завершение спринта.\n\n## Как открыть\nПроект Scrum → `/p/КОД/scrum`.\n\n## Зоны интерфейса\n- **Бэклог** - задачи вне текущего спринта.\n- **Спринт** - колонки активного спринта.\n- Панель **планирования спринта** - перенос задач из бэклога.\n\n## Основные действия\n1. Создайте спринт и задайте даты.\n2. Перенесите задачи из бэклога в спринт.\n3. Ведите задачи по колонкам до «Готово».\n4. **Завершите спринт** - незакрытые задачи вернутся в бэклог или перейдут по правилам проекта.\n\n## Советы\nНе смешивайте Kanban-привычки: в Scrum статус привязан к спринту.\n\n![Схема интерфейса](/static/source/help/illustrations/doc-preview.svg)',
    title = 'Доска Scrum'
from help_doc_section s
where a.section_id = s.id and s.kind = 'page' and s.slug = 'board-scrum' and a.slug = 'guide';

update help_doc_article a
set body_md = E'## Что это\nМодальное окно **создания задачи** открывается с любой страницы по кнопке **«+»** в шапке. Не нужно переходить на доску заранее.\n\n## Поля формы\n- **Проект и доска** - куда попадёт задача.\n- **Название** - обязательно, отображается на карточке.\n- **Описание** - детали для исполнителя.\n- **Исполнитель** - участник команды.\n- **Приоритет** - влияет на фильтры и отчёты.\n- **Сроки** - дата начала и окончания (если заполнены).\n\n## Порядок действий\n1. Нажмите «+» в шапке.\n2. Выберите проект → доску.\n3. Заполните название и при необходимости описание.\n4. Назначьте исполнителя и приоритет.\n5. Сохраните - задача появится на доске в начальном статусе.\n\n## После сохранения\nМожно сразу открыть карточку задачи для вложений или подзадач.\n\n![Схема интерфейса](/static/source/help/illustrations/doc-preview.svg)',
    title = 'Окно создания задачи'
from help_doc_section s
where a.section_id = s.id and s.kind = 'modal' and s.slug = 'create-task' and a.slug = 'guide';

update help_doc_article a
set body_md = E'## Что это\n**Карточка задачи** - полный просмотр и редактирование: статус, люди, описание, подзадачи, вложения, история.\n\n## Как открыть\n- Клик по задаче на **сводке**, в **таблице «Задачи»** или на **доске**.\n- Окно открывается поверх страницы (модально).\n\n## Что внутри\n- Заголовок и код задачи.\n- Описание (редактируемое).\n- Исполнитель, приоритет, сроки.\n- **Подзадачи** - чек-лист.\n- **Вложения** - на Kanban/Scrum (загрузка файлов).\n- Лента изменений статуса.\n\n## Как закрыть\nКрестик, клик по затемнённому фону или клавиша **Escape**.\n\n## Советы\nПосле SPA-перехода между страницами, если окно «залипло», обновите страницу - модалка переинициализируется.\n\n![Схема интерфейса](/static/source/help/illustrations/doc-preview.svg)',
    title = 'Карточка задачи'
from help_doc_section s
where a.section_id = s.id and s.kind = 'modal' and s.slug = 'task-detail' and a.slug = 'guide';

update help_doc_article a
set body_md = E'## Что это\nОкно **профиля** - личные данные: имя, фамилия, отчество, дата рождения, аватар, смена пароля.\n\n## Как открыть\nИконка **профиля** в шапке (справа).\n\n## Что можно изменить\n- ФИО и отображаемое имя.\n- **Дату рождения** (календарь с выбором года).\n- **Аватар** - загрузка изображения.\n- **Пароль** - отдельная форма внутри профиля.\n\n## Сохранение\nНажмите «Сохранить» внизу формы. Ошибки валидации показываются под полями.\n\n![Схема интерфейса](/static/source/help/illustrations/doc-preview.svg)',
    title = 'Профиль пользователя'
from help_doc_section s
where a.section_id = s.id and s.kind = 'modal' and s.slug = 'profile' and a.slug = 'guide';

update help_doc_article a
set body_md = E'## Что это\nОкно **настроек** - параметры интерфейса и уведомлений в рамках реализованных опций TaskPulse.\n\n## Как открыть\nИконка **шестерёнки** в шапке.\n\n## Типичные опции\n- Переключение темы (дублирует кнопку солнца/луны в шапке).\n- Параметры уведомлений (если включены).\n- Язык интерфейса (если доступен).\n\n## Сохранение\nИзменения применяются после подтверждения в модальном окне; часть настроек действует сразу.\n\n![Схема интерфейса](/static/source/help/illustrations/doc-preview.svg)',
    title = 'Настройки'
from help_doc_section s
where a.section_id = s.id and s.kind = 'modal' and s.slug = 'settings' and a.slug = 'guide';
